import {getDiscipline} from './disciplines.js';
import {RELEASE_NOTES_VERSION,RELEASE_NOTES} from './release-notes.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const genderName=(gender,locale)=>({male:locale==='en'?'Male':'남성',female:locale==='en'?'Female':'여성',unspecified:locale==='en'?'Unspecified':'미지정'}[gender]);

export function renderOnboardingFlow(){return `<section class="onboarding-flow" aria-labelledby="onboarding-flow-heading"><h3 id="onboarding-flow-heading">먼저, 어디서 무엇을 하나요?</h3><p>전공 지식 없이도 플레이할 수 있습니다. 문제를 푸는 게임이 아니라 학생의 말과 수행 보고를 보고 일정·업무·연구비를 선택하는 게임입니다.</p><div class="onboarding-menu-map"><article><strong>학생 지도</strong><p>이번 달 주별 계획 · 교수 업무 · 연구실 예산</p></article><article><strong>연구 기록</strong><p>지난 수행과 연구 성과 · 저장점 보관·불러오기</p></article><article><strong>메일함</strong><p>지도 종료 뒤 편지 · 학생의 CV 다시 보기</p></article></div><ol class="onboarding-month-flow"><li>학생 제안을 듣고</li><li>일정·업무·예산을 정하고</li><li>한 달을 진행한 뒤</li><li>수행 보고로 다음 달을 고칩니다.</li></ol><p class="small-note">첫 면담 뒤 실제 화면을 짧게 안내합니다. 건너뛰어도 되고, 상단 “플레이 안내”에서 언제든 다시 볼 수 있습니다. 연구비가 부족한 달도 차액을 자동 차입해 진행할 수 있습니다.</p></section>`;}

export function renderAdmissionInterview({candidates,profile,professorName,selected,locale='ko',releaseVersion=RELEASE_NOTES_VERSION}){return `<section class="welcome admission-interview"><h2>이번 학기 입학면접</h2><p>${esc(professorName)} · ${esc(getDiscipline(profile.fieldId).label)} · ${profile.labMode==='wet'?'Wet lab':'Dry lab'} · ${profile.difficulty==='beginner'?'신임교수(쉬움)':'현실(보통)'}</p><p>세 지원자의 성적, 관심 분야와 면접에서 나눈 이야기를 읽고 한 명을 선택하세요. 연구실 생활은 함께 지내며 알아갑니다.</p><form id="admission-form"><fieldset class="admission-candidates"><legend>지도할 학생 한 명 선택</legend>${candidates.map(c=>`<label class="candidate-option ${selected===c.index?'selected':''}"><input type="radio" name="candidateIndex" value="${c.index}" ${selected===c.index?'checked':''} required><article><div class="candidate-heading"><strong>${esc(c.name)}</strong><span>${genderName(c.gender,locale)} · 학점 ${c.gpa.toFixed(2)} / 4.5</span></div><dl><div><dt>관심 분야</dt><dd>${esc(c.interest)}</dd></div><div><dt>면접 인상</dt><dd>${esc(c.impression)}</dd></div></dl></article></label>`).join('')}</fieldset><p class="small-note">이번 면접의 후보는 새로고침해도 유지됩니다. 성적과 짧은 면접 인상이 학생의 모든 모습을 설명하지는 않습니다.</p><button type="submit" class="primary">선택한 학생과 첫 면담 시작 →</button></form><button type="button" class="text-button update-replay" data-ui="update-open">${esc(releaseVersion)} 변경사항 다시 보기 →</button></section>`;}

export function renderUpdateNotice({version=RELEASE_NOTES_VERSION,title=RELEASE_NOTES.title,changes=RELEASE_NOTES.changes}={}){return `<div class="screen-guide-top"><span>이번 업데이트 · ${esc(version)}</span><button class="text-button" type="button" data-ui="update-close" aria-label="업데이트 안내 닫기">닫기</button></div><div class="update-notice-body"><h2 id="update-notice-title">${esc(title)}</h2><ul>${changes.map(text=>`<li>${esc(text)}</li>`).join('')}</ul><p>학생 지도와 연구실 운영이 조금 더 이해하기 쉽도록 점검하고 보수했습니다.</p></div><button class="primary" type="button" data-ui="update-close">알겠어요 · 시작 준비하기 →</button>`;}
